import json,re,xml.etree.ElementTree as ET
from pathlib import Path
import openpyxl
ROOT=Path.cwd()
def rows(f): return [{c.tag:c.text or '' for c in r} for r in ET.parse(ROOT/'tmp/uml'/f).findall('.//Row')]
ucs={r['Name'].split()[0]:r for r in rows('usecases.xml') if r['Package_ID']=='83'}
w=openpyxl.load_workbook(ROOT/'DocumentacionResumenRequisitos (1) (1).xlsx',data_only=True)
sheet=w['Req. Funcionales']
excel=[]
for row in sheet:
    vals=[c.value for c in row]
    if any(isinstance(v,str) and re.fullmatch(r'RF-\d+(?:-\d+)?',v.strip()) for v in vals):
        excel.append({'row':row[0].row,'values':vals})
(ROOT/'tmp/uml/excel.json').write_text(json.dumps(excel,ensure_ascii=False,default=str,indent=2),encoding='utf-8')
# Each operation is an alternative invocation, never a compulsory CRUD pipeline.
# Step format: subrequirements | action in infinitive. A guard is checked before
# its successful effects; all rejected paths end without those effects.
D={}
def add(n,cls,*scenarios): D[n]={'class':cls,'scenarios':list(scenarios)}
def sc(name,actor,request,check,guard,fail,*steps):
    return dict(name=name,actor=actor,request=request,check=check,guard=guard,fail=fail,steps=[dict(refs=a.split(','),text=b) for a,b in steps])
