# Explicit conditional effects. These become UML decisions/merges and opt
# fragments rather than unconditional messages with a conditional sentence.
def cond(n,s,j,guard,text=None,otherwise=None):
    t=D[n]['scenarios'][s]['steps'][j];t['when']=guard
    if text:t['text']=text
    if otherwise:t['otherwise']=otherwise
