# Results tied to source rows are included in the delivered traceability report.
excel_by_code={r['values'][0].strip():r for r in excel}
for code,uc in ucs.items():
    source=excel_by_code[code]['values']
    assert source[2].strip()==uc['Name'].split(' ',1)[1].strip(),('nombre',code)
    assert source[3].strip() in uc['Note'],('descripción',code)
result=[]
for n,d in D.items():
    code=f'RF-{n:02}'; uc=ucs[code]
    d.update(code=code,name=uc['Name'].split(' ',1)[1],uc=int(uc['Object_ID']),notes=uc['Note'],module=uc['Note'].splitlines()[0].split('|')[-1].strip())
    d['requirements']=[]
    for k,v in ucs.items():
        if k==code or k.startswith(code+'-'): d['requirements'].append(dict(code=k,id=int(v['Object_ID']),name=v['Name'],notes=v['Note']))
    seen=set()
    for s in d['scenarios']:
        for step in s['steps']:
            step['refs']=[code+'-'+x if x else code for x in step['refs']]
            for r in step['refs']:
                assert r in ucs, r
                seen.add(r)
    missing={r['code'] for r in d['requirements'] if r['code']!=code}-seen
    assert not missing,(code,missing)
    result.append(d)
(ROOT/'tmp/uml/spec.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
print('RF',len(result),'subrequisitos',sum(len(d['requirements'])-1 for d in result),'escenarios',sum(len(d['scenarios']) for d in result),'filas Excel',len(excel))
